  private void makeUberDecision(long dataInputLength) {
    int sysMaxMaps = conf.getInt(MRJobConfig.JOB_UBERTASK_MAXMAPS, 9);
    int sysMaxReduces = conf.getInt(MRJobConfig.JOB_UBERTASK_MAXREDUCES, 1);
    long sysMaxBytes = conf.getLong(MRJobConfig.JOB_UBERTASK_MAXBYTES,
        fs.getDefaultBlockSize(remoteJobSubmitDir));

    long sysMemSizeForUberSlot = conf.getInt(MRJobConfig.MR_AM_VMEM_MB,
        MRJobConfig.DEFAULT_MR_AM_VMEM_MB);
    long sysCPUSizeForUberSlot = conf.getInt(MRJobConfig.MR_AM_CPU_VCORES,
        MRJobConfig.DEFAULT_MR_AM_CPU_VCORES);

    boolean uberEnabled = conf.getBoolean(MRJobConfig.JOB_UBERTASK_ENABLE, false);
    boolean smallNumMapTasks = numMapTasks <= sysMaxMaps;
    boolean smallNumReduceTasks = numReduceTasks <= sysMaxReduces;
    boolean smallInput = dataInputLength <= sysMaxBytes;

    long requiredMapMB = conf.getLong(MRJobConfig.MAP_MEMORY_MB, 0);
    long requiredReduceMB = conf.getLong(MRJobConfig.REDUCE_MEMORY_MB, 0);
    long requiredMB = Math.max(requiredMapMB, requiredReduceMB);
    int requiredMapCores = conf.getInt(MRJobConfig.MAP_CPU_VCORES,
        MRJobConfig.DEFAULT_MAP_CPU_VCORES);
    int requiredReduceCores = conf.getInt(MRJobConfig.REDUCE_CPU_VCORES,
        MRJobConfig.DEFAULT_REDUCE_CPU_VCORES);
    int requiredCores = Math.max(requiredMapCores, requiredReduceCores);
    if (numReduceTasks == 0) {
      requiredMB = requiredMapMB;
      requiredCores = requiredMapCores;
    }

    boolean smallMemory = (requiredMB <= sysMemSizeForUberSlot)
        || (sysMemSizeForUberSlot == JobConf.DISABLED_MEMORY_LIMIT);
    boolean smallCpu = requiredCores <= sysCPUSizeForUberSlot;
    boolean notChainJob = !isChainJob(conf);

    isUber = uberEnabled && smallNumMapTasks && smallNumReduceTasks
        && smallInput && smallMemory && smallCpu && notChainJob;

    if (isUber) {
      LOG.info("Uberizing job " + jobId + ": " + numMapTasks + "m+"
          + numReduceTasks + "r tasks (" + dataInputLength
          + " input bytes) will run sequentially on single node.");

      conf.setFloat(MRJobConfig.COMPLETED_MAPS_FOR_REDUCE_SLOWSTART, 1.0f);
      conf.setInt(MRJobConfig.MAP_MAX_ATTEMPTS, 1);
      conf.setInt(MRJobConfig.REDUCE_MAX_ATTEMPTS, 1);
      conf.setBoolean(MRJobConfig.MAP_SPECULATIVE, false);
      conf.setBoolean(MRJobConfig.REDUCE_SPECULATIVE, false);
    } else {
      StringBuilder msg = new StringBuilder();
      msg.append("Not uberizing ").append(jobId).append(" because:");
      if (!uberEnabled) msg.append(" not enabled;");
      if (!smallNumMapTasks) msg.append(" too many maps;");
      if (!smallNumReduceTasks) msg.append(" too many reduces;");
      if (!smallInput) msg.append(" too much input;");
      if (!smallCpu) msg.append(" too much CPU;");
      if (!smallMemory) msg.append(" too much RAM;");
      if (!notChainJob) msg.append(" chainjob;");
      LOG.info(msg.toString());
    }
  }

  private boolean isChainJob(Configuration conf) {
    try {
      String mapClassName = conf.get(MRJobConfig.MAP_CLASS_ATTR);
      if (mapClassName != null) {
        Class<?> mapClass = Class.forName(mapClassName);
        if (ChainMapper.class.isAssignableFrom(mapClass)) {
          return true;
        }
      }
    } catch (ClassNotFoundException | NoClassDefFoundError ignored) {
    }
    try {
      String reduceClassName = conf.get(MRJobConfig.REDUCE_CLASS_ATTR);
      if (reduceClassName != null) {
        Class<?> reduceClass = Class.forName(reduceClassName);
        if (ChainReducer.class.isAssignableFrom(reduceClass)) {
          return true;
        }
      }
    } catch (ClassNotFoundException | NoClassDefFoundError ignored) {
    }
    return false;
  }

  private void actOnUnusableNode(NodeId nodeId, NodeState nodeState) {
    List<TaskAttemptId> taskAttemptIdList = nodesToSucceededTaskAttempts.get(nodeId);
    if (taskAttemptIdList != null) {
      String mesg = "TaskAttempt killed because it ran on unusable node " + nodeId;
      for (TaskAttemptId id : taskAttemptIdList) {
        if (TaskType.MAP == id.getTaskId().getTaskType()) {
          LOG.info(mesg + ". AttemptId:" + id);
          eventHandler.handle(new TaskAttemptKillEvent(id, mesg));
        }
      }
    }
  }

  private static String getWorkflowAdjacencies(Configuration conf) {
    int prefixLen = MRJobConfig.WORKFLOW_ADJACENCY_PREFIX_STRING.length();
    Map<String, String> adjacencies = conf.getValByRegex(
        MRJobConfig.WORKFLOW_ADJACENCY_PREFIX_PATTERN);
    if (adjacencies.isEmpty()) {
      return "";
    }
    StringBuilder sb = new StringBuilder();
    for (Entry<String, String> entry : adjacencies.entrySet()) {
      sb.append("\"")
          .append(escapeString(entry.getKey().substring(prefixLen)))
          .append("\"=\"")
          .append(escapeString(entry.getValue()))
          .append("\" ");
    }
    return sb.toString();
  }

  public static String escapeString(String data) {
    return StringUtils.escapeString(data, StringUtils.ESCAPE_CHAR,
        new char[] { '"', '=', '.' });
  }

  public static class InitTransition
      implements MultipleArcTransition<JobImpl, JobEvent, JobStateInternal> {

    @Override
    public JobStateInternal transition(JobImpl job, JobEvent event) {
      job.metrics.submittedJob(job);
      job.metrics.preparingJob(job);
      job.initializeJobContext();
      try {
        job.setupJob();
        job.fs = job.getFileSystem(job.conf);
        job.logJobSubmittedEvent();
        TaskSplitMetaInfo[] splits = job.createSplits();
        job.numMapTasks = splits.length;
        job.numReduceTasks = job.conf.getInt(MRJobConfig.NUM_REDUCES, 0);
        job.configureWeights();
        job.checkTaskLimits();
        long inputLength = job.computeInputLength(splits);
        job.makeUberDecision(inputLength);
        job.initializeTaskLists();
        job.createMapTasks(splits);
        job.createReduceTasks();
        job.metrics.endPreparingJob(job);
        return JobStateInternal.INITED;
      } catch (Exception e) {
        LOG.warn("Job init failed", e);
        job.metrics.endPreparingJob(job);
        job.addDiagnostic("Job init failed : " + StringUtils.stringifyException(e));
        return JobStateInternal.NEW;
      }
    }

    private void initializeJobContext(JobImpl job) {
      if (job.newApiCommitter) {
        job.jobContext = new JobContextImpl(job.conf, job.oldJobId);
      } else {
        job.jobContext = new org.apache.hadoop.mapred.JobContextImpl(
            job.conf, job.oldJobId);
      }
    }

    private void setupJob(JobImpl job) throws IOException {
      String oldJobIDString = job.oldJobId.toString();
      String user = UserGroupInformation.getCurrentUser().getShortUserName();
      Path path = MRApps.getStagingAreaDir(job.conf, user);
      LOG.debug("startJobs: parent=" + path + " child=" + oldJobIDString);
      job.remoteJobSubmitDir = FileSystem.get(job.conf).makeQualified(
          new Path(path, oldJobIDString));
      job.remoteJobConfFile = new Path(job.remoteJobSubmitDir,
          MRJobConfig.JOB_CONF_FILE);
      JobTokenIdentifier identifier = new JobTokenIdentifier(
          new Text(oldJobIDString));
      job.jobToken = new Token<>(identifier, job.jobTokenSecretManager);
      job.jobToken.setService(identifier.getJobId());
      job.jobTokenSecretManager.addTokenForJob(oldJobIDString, job.jobToken);
      LOG.info("Adding job token for " + oldJobIDString
          + " to jobTokenSecretManager");
      if (TokenCache.getShuffleSecretKey(job.jobCredentials) == null) {
        LOG.warn("Shuffle secret key missing from job credentials."
            + " Using job token secret as shuffle secret.");
        TokenCache.setShuffleSecretKey(job.jobToken.getPassword(),
            job.jobCredentials);
      }
    }

    private void logJobSubmittedEvent(JobImpl job) {
      JobSubmittedEvent jse = new JobSubmittedEvent(job.oldJobId,
          job.conf.get(MRJobConfig.JOB_NAME, "test"),
          job.conf.get(MRJobConfig.USER_NAME, "mapred"),
          job.appSubmitTime,
          job.remoteJobConfFile.toString(),
          job.jobACLs,
          job.queueName,
          job.conf.get(MRJobConfig.WORKFLOW_ID, ""),
          job.conf.get(MRJobConfig.WORKFLOW_NAME, ""),
          job.conf.get(MRJobConfig.WORKFLOW_NODE_NAME, ""),
          getWorkflowAdjacencies(job.conf),
          job.conf.get(MRJobConfig.WORKFLOW_TAGS, ""));
      job.eventHandler.handle(new JobHistoryEvent(job.jobId, jse));
    }

    private TaskSplitMetaInfo[] createSplits(JobImpl job) {
      try {
        return SplitMetaInfoReader.readSplitMetaInfo(
            job.oldJobId, job.fs, job.conf, job.remoteJobSubmitDir);
      } catch (IOException e) {
        throw new YarnRuntimeException(e);
      }
    }

    private void configureWeights(JobImpl job) {
      if (job.numMapTasks == 0 && job.numReduceTasks == 0) {
        job.addDiagnostic("No of maps and reduces are 0 " + job.jobId);
      } else if (job.numMapTasks == 0) {
        job.reduceWeight = 0.9f;
      } else if (job.numReduceTasks == 0) {
        job.mapWeight = 0.9f;
      } else {
        job.mapWeight = job.reduceWeight = 0.45f;
      }
    }

    private void checkTaskLimits(JobImpl job) {
      // placeholder for future task limit checks
    }

    private long computeInputLength(JobImpl job, TaskSplitMetaInfo[] splits) {
      long total = 0;
      for (TaskSplitMetaInfo split : splits) {
        total += split.getInputDataLength();
      }
      return total;
    }

    private void initializeTaskLists(JobImpl job) {
      job.taskAttemptCompletionEvents = new ArrayList<>(
          job.numMapTasks + job.numReduceTasks + 10);
      job.mapAttemptCompletionEvents = new ArrayList<>(
          job.numMapTasks + 10);
      job.taskCompletionIdxToMapCompletionIdx = new ArrayList<>(
          job.numMapTasks + job.numReduceTasks + 10);
      job.allowedMapFailuresPercent = job.conf.getInt(
          MRJobConfig.MAP_FAILURES_MAX_PERCENT, 0);
      job.allowedReduceFailuresPercent = job.conf.getInt(
          MRJobConfig.REDUCE_FAILURES_MAXPERCENT, 0);
    }

    private void createMapTasks(JobImpl job, TaskSplitMetaInfo[] splits) {
      for (int i = 0; i < job.numMapTasks; ++i) {
        TaskImpl task = new MapTaskImpl(job.jobId, i,
            job.eventHandler,
            job.remoteJobConfFile,
            job.conf,
            splits[i],
            job.taskAttemptListener,
            job.jobToken,
            job.jobCredentials,
            job.clock,
            job.applicationAttemptId.getAttemptId(),
            job.metrics,
            job.appContext);
        job.addTask(task);
      }
      LOG.info("Input size for job " + job.jobId + " = "
          + job.computeInputLength(splits) + ". Number of splits = " + splits.length);
    }

    private void createReduceTasks(JobImpl job) {
      for (int i = 0; i < job.numReduceTasks; i++) {
        TaskImpl task = new ReduceTaskImpl(job.jobId, i,
            job.eventHandler,
            job.remoteJobConfFile,
            job.conf,
            job.numMapTasks,
            job.taskAttemptListener,
            job.jobToken,
            job.jobCredentials,
            job.clock,
            job.applicationAttemptId.getAttemptId(),
            job.metrics,
            job.appContext);
        job.addTask(task);
      }
      LOG.info("Number of reduces for job " + job.jobId + " = " + job.numReduceTasks);
    }
  }

