  private static class TaskAttemptCompletedEventTransition
      implements SingleArcTransition<JobImpl, JobEvent> {
    @Override
    public void transition(JobImpl job, JobEvent event) {
      TaskAttemptCompletionEvent tce = ((JobTaskAttemptCompletedEvent) event)
          .getCompletionEvent();
      tce.setEventId(job.taskAttemptCompletionEvents.size());
      job.taskAttemptCompletionEvents.add(tce);
      int mapEventIdx = -1;
      if (TaskType.MAP.equals(tce.getAttemptId().getTaskId().getTaskType())) {
        mapEventIdx = job.mapAttemptCompletionEvents.size();
        job.mapAttemptCompletionEvents.add(TypeConverter.fromYarn(tce));
      }
      job.taskCompletionIdxToMapCompletionIdx.add(mapEventIdx);
      job.handleObsoleteEvent(tce);
      if (TaskAttemptCompletionEventStatus.SUCCEEDED.equals(tce.getStatus())) {
        job.handleSuccessfulAttempt(tce);
      }
    }
  }

  private void handleObsoleteEvent(TaskAttemptCompletionEvent newEvent) {
    TaskId taskId = newEvent.getAttemptId().getTaskId();
    Integer previousIdx = successAttemptCompletionEventNoMap.remove(taskId);
    if (previousIdx != null) {
      TaskAttemptCompletionEvent previous = taskAttemptCompletionEvents.get(previousIdx);
      previous.setStatus(TaskAttemptCompletionEventStatus.OBSOLETE);
      int mapIdx = taskCompletionIdxToMapCompletionIdx.get(previousIdx);
      if (mapIdx >= 0) {
        TaskCompletionEvent mapEvent = mapAttemptCompletionEvents.get(mapIdx);
        mapAttemptCompletionEvents.set(mapIdx,
            new TaskCompletionEvent(mapEvent.getEventId(),
                mapEvent.getTaskAttemptId(),
                mapEvent.idWithinJob(),
                mapEvent.isMapTask(),
                TaskCompletionEvent.Status.OBSOLETE,
                mapEvent.getTaskTrackerHttp()));
      }
    }
  }

  private void handleSuccessfulAttempt(TaskAttemptCompletionEvent tce) {
    TaskId taskId = tce.getAttemptId().getTaskId();
    successAttemptCompletionEventNoMap.put(taskId, tce.getEventId());
    Task task = tasks.get(taskId);
    TaskAttempt attempt = task.getAttempt(tce.getAttemptId());
    NodeId nodeId = attempt.getNodeId();
    assert nodeId != null;
    nodesToSucceededTaskAttempts.computeIfAbsent(nodeId,
        k -> new ArrayList<>()).add(attempt.getID());
  }

  private static class TaskAttemptFetchFailureTransition
      implements SingleArcTransition<JobImpl, JobEvent> {
    @Override
    public void transition(JobImpl job, JobEvent event) {
      int shufflingReduceTasks = 0;
      for (TaskId taskId : job.reduceTasks) {
        Task task = job.tasks.get(taskId);
        if (TaskState.RUNNING.equals(task.getState())) {
          for (TaskAttempt attempt : task.getAttempts().values()) {
            if (attempt.getPhase() == Phase.SHUFFLE) {
              shufflingReduceTasks++;
              break;
            }
          }
        }
      }
      JobTaskAttemptFetchFailureEvent fetchFailureEvent =
          (JobTaskAttemptFetchFailureEvent) event;
      for (TaskAttemptId mapId : fetchFailureEvent.getMaps()) {
        int failures = job.fetchFailuresMapping.getOrDefault(mapId, 0) + 1;
        job.fetchFailuresMapping.put(mapId, failures);
        float failureRate = shufflingReduceTasks == 0 ? 1.0f
            : (float) failures / shufflingReduceTasks;
        if (failures >= job.getMaxFetchFailuresNotifications()
            && failureRate >= job.getMaxAllowedFetchFailuresFraction()) {
          LOG.info("Too many fetch-failures for output of task attempt: "
              + mapId + " ... raising fetch failure to map");
          job.eventHandler.handle(new TaskAttemptEvent(mapId,
              TaskAttemptEventType.TA_TOO_MANY_FETCH_FAILURE));
          job.fetchFailuresMapping.remove(mapId);
        }
      }
    }
  }

  private static class TaskCompletedTransition
      implements MultipleArcTransition<JobImpl, JobEvent, JobStateInternal> {

    @Override
    public JobStateInternal transition(JobImpl job, JobEvent event) {
      job.completedTaskCount++;
      LOG.info("Num completed Tasks: " + job.completedTaskCount);
      JobTaskEvent taskEvent = (JobTaskEvent) event;
      Task task = job.tasks.get(taskEvent.getTaskID());
      switch (taskEvent.getState()) {
        case SUCCEEDED:
          job.taskSucceeded(task);
          break;
        case FAILED:
          job.taskFailed(task);
          break;
        case KILLED:
          job.taskKilled(task);
          break;
        default:
          break;
      }
      return job.evaluateJobCompletion();
    }

    private JobStateInternal evaluateJobCompletion(JobImpl job) {
      if (job.failedMapTaskCount * 100 > job.allowedMapFailuresPercent * job.numMapTasks
          || job.failedReduceTaskCount * 100 > job.allowedReduceFailuresPercent * job.numReduceTasks) {
        job.setFinishTime();
        String diagnosticMsg = "Job failed as tasks failed. failedMaps:"
            + job.failedMapTaskCount + " failedReduces:" + job.failedReduceTaskCount;
        LOG.info(diagnosticMsg);
        job.addDiagnostic(diagnosticMsg);
        boolean allDone = true;
        for (Task task : job.tasks.values()) {
          if (!task.isFinished()) {
            allDone = false;
            job.eventHandler.handle(new TaskEvent(task.getID(),
                TaskEventType.T_KILL));
          }
        }
        if (allDone) {
          job.eventHandler.handle(new CommitterJobAbortEvent(job.jobId,
              job.jobContext,
              org.apache.hadoop.mapreduce.JobStatus.State.FAILED));
          return JobStateInternal.FAIL_ABORT;
        }
        job.failWaitTriggerScheduledFuture = job.executor.schedule(
            new TriggerScheduledFuture(job,
                new JobEvent(job.getID(), JobEventType.JOB_FAIL_WAIT_TIMEDOUT)),
            job.conf.getInt(MRJobConfig.MR_AM_COMMITTER_CANCEL_TIMEOUT_MS,
                MRJobConfig.DEFAULT_MR_AM_COMMITTER_CANCEL_TIMEOUT_MS),
            TimeUnit.MILLISECONDS);
        return JobStateInternal.FAIL_WAIT;
      }
      return job.checkReadyForCommit();
    }

    private static class TriggerScheduledFuture implements Runnable {
      private final JobEvent toSend;
      private final JobImpl job;

      TriggerScheduledFuture(JobImpl job, JobEvent toSend) {
        this.job = job;
        this.toSend = toSend;
      }

      @Override
      public void run() {
        LOG.info("Sending event " + toSend + " to " + job.getID());
        job.getEventHandler().handle(toSend);
      }
    }
  }

  private static class JobNoTasksCompletedTransition
      implements MultipleArcTransition<JobImpl, JobEvent, JobStateInternal> {
    @Override
    public JobStateInternal transition(JobImpl job, JobEvent event) {
      return job.checkReadyForCommit();
    }
  }

  private static class CommitSucceededTransition
      implements SingleArcTransition<JobImpl, JobEvent> {
    @Override
    public void transition(JobImpl job, JobEvent event) {
      job.logJobHistoryFinishedEvent();
      job.finished(JobStateInternal.SUCCEEDED);
    }
  }

  private static class CommitFailedTransition
      implements SingleArcTransition<JobImpl, JobEvent> {
    @Override
    public void transition(JobImpl job, JobEvent event) {
      JobCommitFailedEvent jcfe = (JobCommitFailedEvent) event;
      job.addDiagnostic("Job commit failed: " + jcfe.getMessage());
      job.eventHandler.handle(new CommitterJobAbortEvent(job.jobId,
          job.jobContext,
          org.apache.hadoop.mapreduce.JobStatus.State.FAILED));
    }
  }

  private static class KilledDuringCommitTransition
      implements SingleArcTransition<JobImpl, JobEvent> {
    @Override
    public void transition(JobImpl job, JobEvent event) {
      job.setFinishTime();
      job.eventHandler.handle(new CommitterJobAbortEvent(job.jobId,
          job.jobContext,
          org.apache.hadoop.mapreduce.JobStatus.State.KILLED));
    }
  }

  private static class KilledDuringAbortTransition
      implements SingleArcTransition<JobImpl, JobEvent> {
    @Override
    public void transition(JobImpl job, JobEvent event) {
      job.unsuccessfulFinish(JobStateInternal.KILLED);
    }
  }

  private static class MapTaskRescheduledTransition
      implements SingleArcTransition<JobImpl, JobEvent> {
    @Override
    public void transition(JobImpl job, JobEvent event) {
      job.completedTaskCount--;
      job.succeededMapTaskCount--;
    }
  }

  private static class KillWaitTaskCompletedTransition
      extends TaskCompletedTransition {
    @Override
    protected JobStateInternal evaluateJobCompletion(JobImpl job) {
      if (job.completedTaskCount == job.tasks.size()) {
        job.setFinishTime();
        job.eventHandler.handle(new CommitterJobAbortEvent(job.jobId,
            job.jobContext,
            org.apache.hadoop.mapreduce.JobStatus.State.KILLED));
        return JobStateInternal.KILL_ABORT;
      }
      return job.getInternalState();
    }
  }

  protected void addDiagnostic(String diag) {
    diagnostics.add(diag);
  }

  private static class DiagnosticsUpdateTransition
      implements SingleArcTransition<JobImpl, JobEvent> {
    @Override
    public void transition(JobImpl job, JobEvent event) {
      job.addDiagnostic(((JobDiagnosticsUpdateEvent) event)
          .getDiagnosticUpdate());
    }
  }

  private static class CounterUpdateTransition
      implements SingleArcTransition<JobImpl, JobEvent> {
    @Override
    public void transition(JobImpl job, JobEvent event) {
      JobCounterUpdateEvent jce = (JobCounterUpdateEvent) event;
      for (JobCounterUpdateEvent.CounterIncrementalUpdate ci : jce
          .getCounterUpdates()) {
        job.jobCounters.findCounter(ci.getCounterKey())
            .increment(ci.getIncrementValue());
      }
    }
  }

  private static class UpdatedNodesTransition
      implements SingleArcTransition<JobImpl, JobEvent> {
    @Override
    public void transition(JobImpl job, JobEvent event) {
      JobUpdatedNodesEvent updateEvent = (JobUpdatedNodesEvent) event;
      for (NodeReport nr : updateEvent.getUpdatedNodes()) {
        NodeState nodeState = nr.getNodeState();
        if (nodeState.isUnusable()) {
          job.actOnUnusableNode(nr.getNodeId(), nodeState);
        }
      }
    }
  }

  private static class InternalTerminationTransition
      implements SingleArcTransition<JobImpl, JobEvent> {
    private final JobStateInternal terminationState;
    private final String jobHistoryString;

    InternalTerminationTransition(JobStateInternal stateInternal,
        String jobHistoryString) {
      this.terminationState = stateInternal;
      this.jobHistoryString = jobHistoryString;
    }

    @Override
    public void transition(JobImpl job, JobEvent event) {
      job.setFinishTime();
      JobUnsuccessfulCompletionEvent failedEvent =
          new JobUnsuccessfulCompletionEvent(job.oldJobId,
              job.finishTime, 0, 0,
              jobHistoryString, job.diagnostics);
      job.eventHandler.handle(new JobHistoryEvent(job.jobId, failedEvent));
      job.finished(terminationState);
    }
  }

  private static class InternalErrorTransition extends InternalTerminationTransition {
    InternalErrorTransition() {
      super(JobStateInternal.ERROR, JobStateInternal.ERROR.toString());
    }
  }

  private static class InternalRebootTransition extends InternalTerminationTransition {
    InternalRebootTransition() {
      super(JobStateInternal.REBOOT, JobStateInternal.ERROR.toString());
    }
  }

  @Override
  public Configuration loadConfFile() throws IOException {
    Path confPath = getConfFile();
    FileContext fc = FileContext.getFileContext(confPath.toUri(), conf);
    Configuration jobConf = new Configuration(false);
    jobConf.addResource(fc.open(confPath), confPath.toString());
    return jobConf;
  }

