	//{{{ processKeyEvent() method
	/**
	 * Forwards key events directly to the input handler.
	 * This is slightly faster than using a KeyListener
	 * because some Swing overhead is avoided.
	 */
	public void processKeyEvent(KeyEvent evt)
	{
		if (shouldSkipProcessing(evt))
			return;

		evt = KeyEventWorkaround.processKeyEvent(evt);
		if (evt == null)
			return;

		dispatchToHandler(evt);

		if (!evt.isConsumed())
			super.processKeyEvent(evt);
	}

	/**
	 * Determines whether the given key event should be ignored.
	 *
	 * @param evt the key event to test
	 * @return {@code true} if processing should be skipped
	 */
	private boolean shouldSkipProcessing(KeyEvent evt)
	{
		if (isClosed())
			return true;

		Component focus = getFocusOwner();

		if (focus instanceof JComponent) {
			if (hasComponentBinding((JComponent) focus, evt))
				return true;
		}

		if (focus instanceof JTextComponent) {
			if (isIgnoredInTextComponent(evt))
				return true;
			if (hasTextComponentKeymap((JTextComponent) focus, evt))
				return true;
		}

		return evt.isConsumed();
	}

	/**
	 * Checks whether a {@code JComponent} has a binding for the given event.
	 *
	 * @param comp the component to inspect
	 * @param evt the key event
	 * @return {@code true} if a binding exists
	 */
	private boolean hasComponentBinding(JComponent comp, KeyEvent evt)
	{
		InputMap map = comp.getInputMap();
		ActionMap am = comp.getActionMap();

		if (map != null && am != null && comp.isEnabled()) {
			Object binding = map.get(KeyStroke.getKeyStrokeForEvent(evt));
			return binding != null && am.get(binding) != null;
		}
		return false;
	}

	/**
	 * Determines whether the key event should be ignored when the focus
	 * owner is a {@code JTextComponent}.
	 *
	 * @param evt the key event
	 * @return {@code true} if the event should be ignored
	 */
	private boolean isIgnoredInTextComponent(KeyEvent evt)
	{
		if (evt.getID() != KeyEvent.KEY_PRESSED)
			return false;

		int code = evt.getKeyCode();
		return code == KeyEvent.VK_BACK_SPACE ||
		       code == KeyEvent.VK_TAB ||
		       code == KeyEvent.VK_ENTER;
	}

	/**
	 * Checks whether the {@code JTextComponent}'s keymap handles the event.
	 *
	 * @param comp the text component
	 * @param evt the key event
	 * @return {@code true} if the keymap provides an action
	 */
	private boolean hasTextComponentKeymap(JTextComponent comp, KeyEvent evt)
	{
		Keymap keymap = comp.getKeymap();
		return keymap.getAction(KeyStroke.getKeyStrokeForEvent(evt)) != null;
	}

	/**
	 * Dispatches the key event to the appropriate handler.
	 *
	 * @param evt the processed key event
	 */
	private void dispatchToHandler(KeyEvent evt)
	{
		switch (evt.getID())
		{
			case KeyEvent.KEY_TYPED:
				if (keyEventInterceptor != null) {
					/* keyEventInterceptor.keyTyped(evt) */;
				}
				else if (inputHandler.isPrefixActive()
					 && !getTextArea().hasFocus()) {
					inputHandler.keyTyped(evt);
				}
				break;
			case KeyEvent.KEY_PRESSED:
				if (keyEventInterceptor != null)
					keyEventInterceptor.keyPressed(evt);
				else
					inputHandler.keyPressed(evt);
				break;
			case KeyEvent.KEY_RELEASED:
				if (keyEventInterceptor != null)
					keyEventInterceptor.keyReleased(evt);
				else
					inputHandler.keyReleased(evt);
				break;
		}
	}
